51	  handler(event: H3Event): unknown | Promise<unknown> {
52	    const route = this["~findRoute"](event);
53	    if (route) {
54	      event.context.params = route.params;
55	      event.context.matchedRoute = route.data;
56	    }
57	    const routeHandler = route?.data.handler || NoHandler;
58	    const middleware = this["~getMiddleware"](event, route as unknown as undefined);
