64	  "~request"(request: ServerRequest, context?: H3EventContext): Response | Promise<Response> {
65	    // Create a new event instance
66	    const event = new H3Event(request, context, this as unknown as H3Type);
67	
68	    // Execute the handler
69	    let handlerRes: unknown | Promise<unknown>;
70	    try {
71	      if (this.config.onRequest) {
72	        const hookRes = this.config.onRequest(event);
73	        handlerRes =
74	          typeof hookRes?.then === "function"
75	            ? hookRes.then(() => this.handler(event))
